CREATE OR REPLACE FUNCTION public.finance_confirm_bank_matches(t uuid,txn uuid,items jsonb,notes text DEFAULT '') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bank_transactions;item jsonb;ident uuid;k text;amt numeric;total numeric:=0;seen text[]:='{}';uid uuid:=auth.uid();BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin confirmation required';END IF;IF jsonb_typeof(items)<>'array' OR jsonb_array_length(items)<1 OR jsonb_array_length(items)>50 THEN RAISE EXCEPTION 'Select 1 to 50 records';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('finance-bank:'||t::text,0));SELECT * INTO b FROM bank_transactions WHERE tenant_id=t AND id=txn FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Bank line unavailable';END IF;PERFORM finance_assert_open(t,b.txn_date);IF b.matched_record_id IS NOT NULL OR EXISTS(SELECT 1 FROM bank_transaction_matches WHERE tenant_id=t AND txn_id=b.id) OR EXISTS(SELECT 1 FROM bank_reconciliation_periods WHERE tenant_id=t AND bank_account_id=b.bank_account_id AND status='closed' AND b.txn_date BETWEEN period_start AND period_end) THEN RAISE EXCEPTION 'Bank line already matched or period closed';END IF;
FOR item IN SELECT * FROM jsonb_array_elements(items) LOOP k:=item->>'type';ident:=(item->>'id')::uuid;IF k||':'||ident::text=ANY(seen) OR EXISTS(SELECT 1 FROM bank_transaction_matches WHERE tenant_id=t AND matched_type=k AND matched_id=ident::text) THEN RAISE EXCEPTION 'Source already selected or matched';END IF;seen:=array_append(seen,k||':'||ident::text);amt:=NULL;
IF k='payment' AND b.money_out>0 THEN SELECT p.amount INTO amt FROM payments p WHERE p.tenant_id=t AND p.id=ident AND p.bank_transaction_id IS NULL AND p.paid_from_account_id=b.bank_account_id AND p.payment_date<=b.txn_date;
ELSIF k='bill_payment' AND b.money_out>0 THEN SELECT p.amount INTO amt FROM expense_bill_payments p JOIN expense_bills eb ON eb.id=p.bill_id AND eb.tenant_id=t WHERE p.tenant_id=t AND p.id=ident AND p.bank_account_id=b.bank_account_id AND p.payment_date<=b.txn_date AND eb.approval_status='posted';
ELSIF k='settlement_batch' AND b.money_in>0 THEN SELECT net_settlement INTO amt FROM payment_settlement_batches WHERE tenant_id=t AND id=ident AND bank_transaction_id IS NULL AND settlement_date<=b.txn_date AND (bank_account_id IS NULL OR bank_account_id=b.bank_account_id);
ELSE RAISE EXCEPTION 'Match recorded payments or payout batches; invoices without payment evidence stay unpaid';END IF;
IF amt IS NULL OR amt<=0 OR amt<>round(amt,2) THEN RAISE EXCEPTION 'Source unavailable or amount invalid';END IF;total:=total+amt;INSERT INTO bank_transaction_matches(tenant_id,txn_id,matched_type,matched_id,amount,confidence,notes,created_by) VALUES(t,b.id,k,ident::text,amt,'high',left(notes,3000),uid);END LOOP;
IF total<>greatest(b.money_in,b.money_out) OR b.money_in>0 AND b.money_out>0 THEN RAISE EXCEPTION 'Selected records must exactly equal the bank line';END IF;
UPDATE bank_transactions SET matched_record_type=CASE WHEN jsonb_array_length(items)>1 THEN 'multiple' ELSE items->0->>'type' END,matched_record_id=CASE WHEN jsonb_array_length(items)>1 THEN 'multi:'||b.id ELSE items->0->>'id' END,status='matched',match_confidence='high',notes=left(notes,3000) WHERE tenant_id=t AND id=b.id;
INSERT INTO audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,uid,'bank_multi_match_confirmed','bank_transactions',b.id::text,jsonb_build_object('items',items,'amount',total,'notes',notes));END $$;
REVOKE ALL ON FUNCTION public.finance_confirm_bank_matches(uuid,uuid,jsonb,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_confirm_bank_matches(uuid,uuid,jsonb,text) TO authenticated;